import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.Bx6eOp9J.js";const u=JSON.parse('{"title":"2026-10-27 Agent 核心研究与竞品动态","description":"CatchBench 接入 auditable、自适应网关验证、工具调用前审查、幂等恢复及竞品交付变化。","frontmatter":{"title":"2026-10-27 Agent 核心研究与竞品动态","description":"CatchBench 接入 auditable、自适应网关验证、工具调用前审查、幂等恢复及竞品交付变化。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-10-27.md","filePath":"zh/runtime/daily-intelligence/2026-10-27.md","lastUpdated":1793106296000}'),n={name:"zh/runtime/daily-intelligence/2026-10-27.md"};function p(l,e,i,s,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-10-27-agent-核心研究与竞品动态" tabindex="-1">2026-10-27 Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-10-27-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-10-27 Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮最重要的变化是：<strong>审计从“有日志”走向验证真实调用链，恢复从“重试”走向持久身份与所有权，授权从静态声明走向最终执行参数。</strong> 赵越相关 CatchBench 与 AEGIS 分别补强方法库消费证据和真正触达网关的攻击检验；Paperclip、Eigent 等在修重复执行与不完整证明；Superset 更名为 Paradev 并发布 desktop 2.0.0。</p><p>执行起点：2026-10-27 20:50:12（Asia/Shanghai）。主要增量窗口：2026-10-26 10:01:41 至本次起点；依据上轮成功核查和已发布 10 月 26 日日档去重。未完成来源保留更早待查起点，不把旧材料冒充当天新增。以下 CodeFlowMu/FCoP 关系均是<strong>待验证线索</strong>，不是开发派工或已完成实验。</p><h2 id="_1-赵越-catchbench-0-1-3-把基线真正接入-auditable" tabindex="-1">1. 赵越：CatchBench 0.1.3 把基线真正接入 auditable <a class="header-anchor" href="#_1-赵越-catchbench-0-1-3-把基线真正接入-auditable" aria-label="Permalink to &quot;1. 赵越：CatchBench 0.1.3 把基线真正接入 auditable&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>10 月 26 日 11:01（北京时间）正式发行。79 个榜单条目改由 auditable ≥0.3.0 计算；LLM judge 的缓存经库构建提示、解析回复并逐项核对，偏差会报错。新增消费测试：让旧评分核心抛错仍能完成榜单，扰动库输出则对应条目必须变化。数据、标签、划分、协议和指标不变，榜单与 0.1.2 数值完全相同。这是实现与可复现性变化，不能写成性能提升。</p><p>CodeFlowMu/FCoP 待验证线索：评测应验证生产方法库确实参与计算，防止 benchmark 与实际实现分叉。值得互动：迁移条目如何覆盖配置前审计、运行中预警和事后归因，以及未迁移基线为何保留。</p><p>原始来源：<a href="https://github.com/yzhao062/catchbench/releases/tag/v0.1.3" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://pypi.org/project/catchbench/0.1.3/" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_2-赵越相关-aegis-换用会执行注入的-agent-检验网关" tabindex="-1">2. 赵越相关 AEGIS：换用会执行注入的 Agent 检验网关 <a class="header-anchor" href="#_2-赵越相关-aegis-换用会执行注入的-agent-检验网关" aria-label="Permalink to &quot;2. 赵越相关 AEGIS：换用会执行注入的 Agent 检验网关&quot;">​</a></h2><p><strong>状态：COMMITTED; UPSTREAM RESULTS, NOT LOCALLY REPRODUCED</strong></p><p>Justin0504/Aegis 的 9cc08d1 提交新增自适应 AgentDojo 实验及结果。原 Haiku 4.5 实验中，Agent 没有执行攻击，不能据此证明网关挡住攻击；新实验用本地 qwen3-8b，在 banking/slack 的 249 对攻击里，无防御时实际执行 61 对，再对这 61 对做四轮改写。仅判决反馈和白盒反馈两组，均标记/挂起 60/61（98.4%），各有 1/61 逃逸。逃逸需同时满足 AgentDojo 安全判定成功和网关允许 sink 工具。数据是上游自报，未本地复现，不能推成普适安全率或零逃逸。</p><p>作者归属由 README 的 Aojie Yuan、Zhiyuan Su、赵越及 USC FORTIS 链接确认，不把任意同名 Aegis 归给赵越。待验证线索：必须区分“模型自己拒绝”和“网关真正阻断”；互动可追问那一个逃逸的路径、良性多步误挂起成本和 hold 的最终审批语义。</p><p>原始来源：<a href="https://github.com/Justin0504/Aegis/commit/9cc08d10f31bf6ba2511a526db2ee14324863924" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/Justin0504/Aegis/blob/9cc08d10f31bf6ba2511a526db2ee14324863924/research/paper-arxiv/figures/table_adaptive_agentdojo.tex" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_3-codex-原生工具调用前-guardian-审查与跨进程会话锁" tabindex="-1">3. Codex：原生工具调用前 Guardian 审查与跨进程会话锁 <a class="header-anchor" href="#_3-codex-原生工具调用前-guardian-审查与跨进程会话锁" aria-label="Permalink to &quot;3. Codex：原生工具调用前 Guardian 审查与跨进程会话锁&quot;">​</a></h2><p><strong>状态：MERGED; STABLE RELEASE NOT VERIFIED</strong></p><p>#57433 在 opted-in 原生函数调用分发前同步审查；拒绝时 handler 不执行。若 hook 改写参数，审查改写后的参数并丢弃原加密回放内容。#57441 注册原生多 Agent 历史功能开关，仍处开发中、默认关闭。#57358 用持久锁协调多个进程修改 session_index.jsonl，竞争 30 秒超时不写入，调用方取消后仍持锁直至阻塞 worker 完成。最新稳定版仍为 0.164.0；新 alpha 不能证明这些能力已进入稳定版。</p><p>待验证线索：call-time authorization 必须绑定最后实际执行参数；取消请求不能提前释放写锁。值得互动：hook 改写、审查重试、证据预算截断与多 Agent 历史缺口如何共同影响授权。</p><p>原始来源：<a href="https://github.com/openai/codex/pull/57433" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/openai/codex/pull/57441" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/openai/codex/pull/57358" target="_blank" rel="noreferrer">证据 3</a> · <a href="https://github.com/openai/codex/releases/tag/rust-v0.164.0" target="_blank" rel="noreferrer">证据 4</a></p><h2 id="_4-openai-agents-python-可选-handoff-纠错不等于副作用回滚" tabindex="-1">4. OpenAI Agents Python：可选 handoff 纠错不等于副作用回滚 <a class="header-anchor" href="#_4-openai-agents-python-可选-handoff-纠错不等于副作用回滚" aria-label="Permalink to &quot;4. OpenAI Agents Python：可选 handoff 纠错不等于副作用回滚&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>#5418 增加可选 failure_error_function，让无效 handoff 参数返回给调用 Agent 修正；None 保留抛异常。已处理失败停留在 caller，不执行成功转交 hook/history filter；应用回调错误可恢复，但不会回滚已发生副作用，取消和 transfer hook/filter 错误继续传播。seratch 的 #5430 仅按 writer 的 LF 分割嵌套 handoff 记录，避免 Unicode/控制字符分隔符把消息误拆成新角色；#5431 要求已修复 MCP 依赖，排除受影响的 2.0/2.1，保留修补后的 1.x/2.x。</p><p>待验证线索：协议错误恢复要与执行幂等、消息角色边界分别验证。值得互动：回调已产生副作用后，哪些错误应重抛而非自动让模型重试。seratch 仍直接参与本轮核心修复。</p><p>原始来源：<a href="https://github.com/openai/openai-agents-python/pull/5418" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/openai/openai-agents-python/pull/5430" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/openai/openai-agents-python/pull/5431" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_5-claude-code-copilot-cli-正式版修长任务与子-agent-生命周期" tabindex="-1">5. Claude Code / Copilot CLI：正式版修长任务与子 Agent 生命周期 <a class="header-anchor" href="#_5-claude-code-copilot-cli-正式版修长任务与子-agent-生命周期" aria-label="Permalink to &quot;5. Claude Code / Copilot CLI：正式版修长任务与子 Agent 生命周期&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>Claude Code 2.1.311 修复 SubagentStop hook 在运行中反复触发、后台子 Agent 尚在工作时隔离 worktree 被删除、晚连接 MCP 工具对子 Agent 不可用，以及重启后已完成子 Agent skill 再跑一次等问题；新增 self-hosted-runner 的 idle hold 参数。Copilot CLI 1.0.104 让交互式及 SDK Autopilot 继续等待已附着后台任务，-p --autopilot 仍遵守原等待超时；Assisted Permissions 不再要求实验模式。</p><p>待验证线索：停止/完成 hook、工作区回收和后台任务等待应基于真实子任务生命周期。值得互动：区分无人值守等待与无界挂起，如何给父会话提供子任务仍活跃的证据。</p><p>原始来源：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.311" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/github/copilot-cli/releases/tag/v1.0.104" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_6-langgraph-1-2-18-恢复路径、最后-checkpoint-与存储取舍" tabindex="-1">6. LangGraph 1.2.18：恢复路径、最后 checkpoint 与存储取舍 <a class="header-anchor" href="#_6-langgraph-1-2-18-恢复路径、最后-checkpoint-与存储取舍" aria-label="Permalink to &quot;6. LangGraph 1.2.18：恢复路径、最后 checkpoint 与存储取舍&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>1.2.18 发布 error_handler 在各路径上的恢复及失败 task 结果流；interrupt_after 或递归上限停止的运行会流出最后 checkpoint。DeltaChannel 默认每 100 次增量保存全量快照，原为 1000，换取长线程读取更快、更多存储，可显式设回 1000。同步发布 SDK 0.4.10 修 runs.wait 重试和 SSE 处理，checkpoint 4.3.1 拒绝 namespace 标签中的 NUL。</p><p>待验证线索：停止时可见的最终状态、错误事件与恢复 checkpoint 必须一致；checkpoint 频率需要结合实际长任务成本评估。值得互动：失败流与恢复后结果的去重及客户端游标语义。</p><p>原始来源：<a href="https://github.com/langchain-ai/langgraph/releases/tag/1.2.18" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/langchain-ai/langgraph/releases/tag/sdk%3D%3D0.4.10" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/langchain-ai/langgraph/releases/tag/checkpoint%3D%3D4.3.1" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_7-mcp-apps-减少示例审批卡-webmcp-桥接仍需守住发行边界" tabindex="-1">7. MCP Apps：减少示例审批卡，WebMCP 桥接仍需守住发行边界 <a class="header-anchor" href="#_7-mcp-apps-减少示例审批卡-webmcp-桥接仍需守住发行边界" aria-label="Permalink to &quot;7. MCP Apps：减少示例审批卡，WebMCP 桥接仍需守住发行边界&quot;">​</a></h2><p><strong>状态：2.0.4 RELEASED; #829/#835 MERGED</strong></p><p>2.0.4 正式版不改库 API：pdf-server 示例把 13 个独立 action 工具收敛成一个 interact，保留 --split-app-tools；批处理按输入位置返回结果，失败项有 ERROR，而不是给整批 isError。#829 随后合入 App/WebMCP 双向桥接与工具去重规则，#835 又回退 2.1.0 版本号提交。当前不能把桥接写成 2.0.4 已有能力或 2.1.0 已发布。</p><p>待验证线索：统一工具入口减少审批噪声，但动作级授权仍需保留；同一 View 经两种表面发现时只消费一种。值得互动：批量动作的局部失败、权限粒度及桥接导致重复执行的防护。</p><p>原始来源：<a href="https://github.com/modelcontextprotocol/ext-apps/releases/tag/v2.0.4" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/modelcontextprotocol/ext-apps/pull/829" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/modelcontextprotocol/ext-apps/pull/835" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_8-paperclip-恢复抢占、完整性证明、windows-保存及-pwa-安装" tabindex="-1">8. Paperclip：恢复抢占、完整性证明、Windows 保存及 PWA 安装 <a class="header-anchor" href="#_8-paperclip-恢复抢占、完整性证明、windows-保存及-pwa-安装" aria-label="Permalink to &quot;8. Paperclip：恢复抢占、完整性证明、Windows 保存及 PWA 安装&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>#17838 阻止启动恢复抢占本服务器仍在准备的 heartbeat，避免基于未完成 workspace descriptor 再启动 executor；#15063 保留子树 100 层上限，但能检测边界外仍有合格子节点，此时返回 incomplete，不生成停止指纹、不派发审查、不允许 mutation。#16925 对同 record 的 ACPX 保存进程内串行，避免 Windows 重叠 rename 的 EPERM；不同记录仍并行。#13461 将 manifest 改为 standalone，使安装 PWA 而非只建浏览器快捷方式；没有增加 Push。</p><p>学习价值高：恢复所有权、扫描完整性与 Windows 文件并发都触及真实生产故障。竞争风险中高，维持主雷达、提高恢复与移动交付关注；不能据此称成熟手机审批终端。待验证：FCoP 证明必须注明是否完整；互动切入点是 incomplete 与 stale proof 的处置，以及进程内队列是否仍需跨进程协调。</p><p>原始来源：<a href="https://github.com/paperclipai/paperclip/pull/17838" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/15063" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/paperclipai/paperclip/pull/16925" target="_blank" rel="noreferrer">证据 3</a> · <a href="https://github.com/paperclipai/paperclip/pull/13461" target="_blank" rel="noreferrer">证据 4</a></p><h2 id="_9-eigent-持久请求-id-解决-automation-重复准入" tabindex="-1">9. Eigent：持久请求 ID 解决 Automation 重复准入 <a class="header-anchor" href="#_9-eigent-持久请求-id-解决-automation-重复准入" aria-label="Permalink to &quot;9. Eigent：持久请求 ID 解决 Automation 重复准入&quot;">​</a></h2><p><strong>状态：MERGED; PACKAGED RELEASE NOT VERIFIED</strong></p><p>#2089 修复后台 Automation 用随机 task ID，导致随后打开 Session 时原请求再次准入；改用 durable queue request ID，由后台事务标记同一请求并去重。#2108 在失败任务完成状态协调和收尾前保留 follow-up 队列，以 1 到 30 秒退避处理 Session busy，接受前不发布消息/切换活动任务，并保留附件。#2089 明确未运行打包应用中的完整 scheduled Automation，不能把测试称为桌面验收。</p><p>学习价值高，竞争风险中高，维持主雷达并增加准入一致性观察。待验证：跨后台、前台和重连都应复用同一请求身份。值得互动：任务已执行但响应丢失时，如何避免重试造成第二次外部副作用。</p><p>原始来源：<a href="https://github.com/eigent-ai/eigent/pull/2089" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/eigent-ai/eigent/pull/2108" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_10-oacp-0-5-4-脚本信任绑定内容哈希" tabindex="-1">10. OACP 0.5.4：脚本信任绑定内容哈希 <a class="header-anchor" href="#_10-oacp-0-5-4-脚本信任绑定内容哈希" aria-label="Permalink to &quot;10. OACP 0.5.4：脚本信任绑定内容哈希&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>0.5.4 的 envelope.trusted_scripts 以 SHA-256 pin 允许运行脚本，pin-script 写 pin 后重签 receiver 配置；doctor 检查缺失/过期 pin。未 pin 脚本请求确认，shell 展开生成程序名时也请求确认；更完整审查 compound commands，并把 ask/deny 记录到 envelope_decisions.jsonl。verify --attach-audit 拒绝贴到另一条消息的记录，finalizer 拒绝没有覆盖证明的 realized grant-only effect。</p><p>学习价值高，竞争风险中，保持专项协议雷达、提高脚本信任与审计绑定关注。待验证：授权对象应是具体内容及执行上下文，而非路径名。值得互动：pin 校验到实际执行之间的 TOCTOU，以及脚本依赖变化是否也进入信任范围。</p><p>原始来源：<a href="https://github.com/kiloloop/oacp/releases/tag/v0.5.4" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_11-orca-1-4-242-ask-模式按实际权限运行-恢复保留授权" tabindex="-1">11. Orca 1.4.242：Ask 模式按实际权限运行，恢复保留授权 <a class="header-anchor" href="#_11-orca-1-4-242-ask-模式按实际权限运行-恢复保留授权" aria-label="Permalink to &quot;11. Orca 1.4.242：Ask 模式按实际权限运行，恢复保留授权&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>1.4.241/242 已正式发行。1.4.242 中 Codex Ask 模式按只读运行，编辑前请求确认；权限修改应用于新 turn，已运行工作保留原 grant，配对服务器需升级才改变旧行为。恢复 Claude 保留 effort/launch flags，Codex 保留最后授权；配对服务器重启保留 tabs，手机对主机不可达给原因。Claude 子 Agent transcript 可从侧栏进入，依赖 status hooks，已运行 session 需新启动。原生 Chat 仍标 experimental。</p><p>学习价值高，竞争风险中高；保持第二圈重点、提高远程权限一致性关注。待验证：手机、桌面、host 版本和每一 turn 的 grant 需要一致且可解释。值得互动：权限收紧后仍运行的旧 grant 如何展示、撤销和审计。</p><p>原始来源：<a href="https://github.com/stablyai/orca/releases/tag/v1.4.242" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_12-uniemployee-0-23-0-研究工作台连同采集、租户与迁移" tabindex="-1">12. UniEmployee 0.23.0：研究工作台连同采集、租户与迁移 <a class="header-anchor" href="#_12-uniemployee-0-23-0-研究工作台连同采集、租户与迁移" aria-label="Permalink to &quot;12. UniEmployee 0.23.0：研究工作台连同采集、租户与迁移&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>0.23.0 发布行业研究工作台，覆盖具身智能、AI 前沿观察与政策分析，提供分类、来源追溯和版本化研判。公开链接流水线包含租户隔离、来源去重、私网地址拦截、断点恢复及证据范围校验。入站研究 MCP 默认关闭，至少 32 字节随机 token 配置后启用；启动自动建表和补技能，保留管理员人设、知识库及用户覆盖。测试通过是发行说明的上游声明，本轮未安装。</p><p>学习价值高、竞争风险中高：从通用员工向垂直研究产品扩展；提高第二圈雷达关注，不仅记成界面变化。待验证：采集任务、证据与综合判断的版本和租户边界。互动可问重定向/DNS rebinding 场景的私网防护和恢复后证据范围。</p><p>原始来源：<a href="https://github.com/zj-unicom-ai/UniEmployee/releases/tag/v0.23.0" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_13-agentlas-os-1-2-70-主机原生委派与执行回执分开" tabindex="-1">13. Agentlas OS 1.2.70：主机原生委派与执行回执分开 <a class="header-anchor" href="#_13-agentlas-os-1-2-70-主机原生委派与执行回执分开" aria-label="Permalink to &quot;13. Agentlas OS 1.2.70：主机原生委派与执行回执分开&quot;">​</a></h2><p><strong>状态：RELEASED</strong></p><p>1.2.70 允许 prepared agents 在当前 host 具备且已授权时使用原生委派；package read allowlist 仅描述包内容，项目与工具权限继续由 host 及显式限制决定。缺少 execution-receipt 遥测不再阻断已获授权的工作，但回执验证仍严格，未经验证的工作不标成 validated execution。</p><p>学习价值高、竞争风险中，保持第二圈观察。待验证：执行许可、实际执行、证据到达和验证通过应是不同事实。值得互动：允许工作继续时，缺失回执如何补交、超时与影响后续 admission。</p><p>原始来源：<a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/v1.2.70" target="_blank" rel="noreferrer">证据 1</a></p><h2 id="_14-superset-正式更名-paradev-2-0-0-与云恢复另分状态" tabindex="-1">14. Superset 正式更名 Paradev：2.0.0 与云恢复另分状态 <a class="header-anchor" href="#_14-superset-正式更名-paradev-2-0-0-与云恢复另分状态" aria-label="Permalink to &quot;14. Superset 正式更名 Paradev：2.0.0 与云恢复另分状态&quot;">​</a></h2><p><strong>状态：RENAME MERGED; DESKTOP 2.0.0 RELEASED; LATER FIXES MERGED</strong></p><p>#8874 于 10 月 26 日合入更名与发布链迁移；旧 superset-sh/superset 跳转 ParadevAI/Paradev，GitHub repository ID 均为 1080370450，确认同一项目。desktop-v2.0.0 正式发行，CLI 新增 paradev 别名但 superset 保留为实际 binary；ELv2 未变为宽松许可，LICENSE 本轮改动与公司名称规范化相关。后续 #8909 合入云端启动/唤醒时排队、liveness gate 和避免重放含糊 in-flight 消息；#8795 的 TOML 配置仍 dark launch，flag 主要面向 team，不能写成全面开放。</p><p>学习价值高、竞争风险高，维持主雷达并记录官方更名映射，不擅自替换其他仓库。待验证：冷启动、恢复、初始 prompt 身份与 outbox 的一致性。值得互动：无回执的 in-flight 消息如何处置，archive hook 失败与资源回收如何共同收敛。产品名称/下载链发生结构变化，不以融资宣传本身作为技术新增。</p><p>原始来源：<a href="https://github.com/ParadevAI/Paradev/pull/8874" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/ParadevAI/Paradev/releases/tag/desktop-v2.0.0" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/ParadevAI/Paradev/pull/8909" target="_blank" rel="noreferrer">证据 3</a> · <a href="https://github.com/ParadevAI/Paradev/pull/8795" target="_blank" rel="noreferrer">证据 4</a> · <a href="https://github.com/ParadevAI/Paradev/blob/main/LICENSE.md" target="_blank" rel="noreferrer">证据 5</a></p><h2 id="_15-crewai-dspy-恢复、模板插值和磁盘缓存均是信任边界" tabindex="-1">15. CrewAI / DSPy：恢复、模板插值和磁盘缓存均是信任边界 <a class="header-anchor" href="#_15-crewai-dspy-恢复、模板插值和磁盘缓存均是信任边界" aria-label="Permalink to &quot;15. CrewAI / DSPy：恢复、模板插值和磁盘缓存均是信任边界&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>CrewAI #8622 在 output_file 模板插值后重新验证，并在最终保存时检查解析路径仍处 cwd，堵住构造时验证被后续输入绕过。#8623 修复 checkpoint tool 恢复的未受信任反序列化、SQL 注释绕过只读检查及 tar 解包竞争。DSPy #10726 默认启用 restricted pickle，未注册磁盘缓存类型变成 cache miss；可信目录可显式 opt out，内存缓存不变。这些 PR 已合入，尚未证明进入正式版，不声称所有反序列化风险消失。</p><p>待验证线索：构造时批准不能覆盖插值后的实际路径；恢复/缓存数据也需信任策略。值得互动：恢复自定义类型的可用性代价，以及 Windows 根路径、符号链接和写入时竞争的剩余边界。</p><p>原始来源：<a href="https://github.com/crewAIInc/crewAI/pull/8622" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/crewAIInc/crewAI/pull/8623" target="_blank" rel="noreferrer">证据 2</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10726" target="_blank" rel="noreferrer">证据 3</a></p><h2 id="_16-openhands-sdk-脱敏不能破坏事件身份-oauth-回调可重放" tabindex="-1">16. OpenHands SDK：脱敏不能破坏事件身份，OAuth 回调可重放 <a class="header-anchor" href="#_16-openhands-sdk-脱敏不能破坏事件身份-oauth-回调可重放" aria-label="Permalink to &quot;16. OpenHands SDK：脱敏不能破坏事件身份，OAuth 回调可重放&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>#6155 修复短 secret 命中 UUID 后把事件 ID 脱敏，造成 EventLog 索引断裂、暂停后无法重载；给 EventID/ToolCallID 标注跳过脱敏，容器内同样识别 ID，但相邻文本仍脱敏。#5866 由 Engel Nyst 直接参与：重复 MCP OAuth callback 对已完成 job 返回保存的状态和 200；仍运行但 callback server 不可达才返回 409，避免把已经成功的授权当成失败。</p><p>待验证线索：审计标识完整性与 secret 脱敏不能互相破坏，重复回调应查持久状态。值得互动：任意字符串 ID 是否需要受控格式约束，避免把真实 secret 藏入“不脱敏 ID”字段。</p><p>原始来源：<a href="https://github.com/OpenHands/software-agent-sdk/pull/6155" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/5866" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_17-ag2-最终回答才能消除-no-answer-超时也不能当回滚" tabindex="-1">17. AG2：最终回答才能消除 no_answer，超时也不能当回滚 <a class="header-anchor" href="#_17-ag2-最终回答才能消除-no-answer-超时也不能当回滚" aria-label="Permalink to &quot;17. AG2：最终回答才能消除 no_answer，超时也不能当回滚&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>#3506 修 failure_attribution：中间一句“我去查一下”不再掩盖最终无答案或工具失败；按最后 ModelResponse 判断，与评测输出投影一致。#3514 增加每次函数工具调用 timeout，覆盖依赖解析、执行和清理，超时形成 ToolErrorEvent；approval middleware 在该计时外。取消是协作式，已超时的同步 worker 仍可能继续运行并产生副作用。</p><p>待验证线索：评价成功、用户收到答案、工具停止及副作用终止是不同事实。值得互动：超时后重试如何绑定同一幂等键，以及 failure attribution 如何记录仍在执行的 worker。</p><p>原始来源：<a href="https://github.com/ag2ai/ag2/pull/3506" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/ag2ai/ag2/pull/3514" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="_18-langfuse-fips-从-enterprise-转入独立-government-授权" tabindex="-1">18. Langfuse：FIPS 从 Enterprise 转入独立 Government 授权 <a class="header-anchor" href="#_18-langfuse-fips-从-enterprise-转入独立-government-授权" aria-label="Permalink to &quot;18. Langfuse：FIPS 从 Enterprise 转入独立 Government 授权&quot;">​</a></h2><p><strong>状态：MERGED; RELEASE NOT VERIFIED</strong></p><p>#19316 合入 self-hosted:gov 与 lf_gov_ license key，包含 Enterprise 权益；Government 模式始终关闭遥测。破坏性边界是 LANGFUSE_REQUIRE_FIPS=true 现在需要 government key，原 enterprise key 升级到包含此变更的版本后会拒绝启动，Cloud 不变。该 PR 合入晚于本轮 v4.70.1 发布，不能把它称为该正式版已带来的行为。</p><p>对评测/可观测性基础设施有实际升级价值；商业边界变化值得跟踪。CodeFlowMu/FCoP 待验证线索：合规能力与 License gate 会影响升级可用性，应在迁移前识别。值得互动：企业 FIPS 用户的迁移窗口、离线 key 验证和失败诊断。</p><p>原始来源：<a href="https://github.com/langfuse/langfuse/pull/19316" target="_blank" rel="noreferrer">证据 1</a> · <a href="https://github.com/langfuse/langfuse/releases/tag/v4.70.1" target="_blank" rel="noreferrer">证据 2</a></p><h2 id="跨项目共振与分类处置" tabindex="-1">跨项目共振与分类处置 <a class="header-anchor" href="#跨项目共振与分类处置" aria-label="Permalink to &quot;跨项目共振与分类处置&quot;">​</a></h2><ul><li><strong>授权绑定真实动作</strong>：Codex 审查 hook 改写后的参数，OACP pin 内容，CrewAI 重验插值后路径。静态批准与调用时检查不能互相替代。</li><li><strong>恢复不能制造第二次执行</strong>：Paperclip 活跃准备所有权、Eigent 请求身份、Paradev outbox、OAuth 回调和文件锁都在收敛这一问题。</li><li><strong>证据应保留边界</strong>：CatchBench 验证库消费；AEGIS 区分模型拒绝与网关阻断；Paperclip 不完整扫描不能证明停止；Agentlas 不把无回执执行称为已验证。</li><li><strong>停止等待不等于停止副作用</strong>：AG2 同步 worker、CLI 后台任务与子 Agent worktree 生命周期需分别处理。</li></ul><p>分类结果：本轮仅收集、筛选与报告。上游实验数据已经注明来源与边界；本地工程实验 0、文章 0、开发评审项目 0、外部评论/互动发送 0。不将研究线索直接转换为评审或派工。互动技术议题已逐项记录。</p><h2 id="双源核查、覆盖与空档" tabindex="-1">双源核查、覆盖与空档 <a class="header-anchor" href="#双源核查、覆盖与空档" aria-label="Permalink to &quot;双源核查、覆盖与空档&quot;">​</a></h2><p>Registry 来自已连接 GitHub 工具读取的 latest main，47 位研究人物，blob 8d97df65269aa2b4accd1366d1b71319f99c6efd。六位治理/验证研究对象及关系边界继续保留；本轮未从其关联仓库确认值得单列的新变化。bulbasaur-skill-cli 仍只是相关项目，不是 AGENTSAFE 官方 Artifact。赵越姓名统一；人物和仓库保持多对多归属。</p><p>核查 88 个仓库目标：Registry 工程源、补充技术项目及 32 个竞品目标。GitHub 来源按 Release、增量 commit、更新 PR/Issue 核查；993 条 commit 记录，48 个无增量仓库另读 default branch 最新 SHA。Superset 原地址返回 301 后，通过网页重定向、相同 repository ID 及官方更名 PR 验证到 Paradev，保留原目标和映射。未逐库穷尽全部架构/License/Discussion；重要变更才读对应原文、文档或许可。</p><p>明确缺口：Codex、Claude Code、Orca 的 PR/Issue 更新列表各查至 12 页仍未完，保留待查窗口；TSA-AI-Workforce 三类接口 404，不推断删除或私有化。Codex 大 release 列表传输失败，回退查最新 3 个与 latest stable 成功，仍仅为有界覆盖。其余 release 列表也只查最近 10 个，不宣称全历史覆盖。来源失败、分页未完与无新增分别记录；不存在一个可声称全覆盖成功的统一水位。</p><p>第二来源类型单列：按实时 47 人分 12 组进行公开社交/作者讨论检索，并实际打开 Cursor 官方 changelog、CatchBench PyPI、Paradev 官方 changelog 与 Audit Commons。检索结果未形成可确认的窗口内新增个人帖子，不代表穷尽 X 时间线。PyPI 支撑包可获取性；工程事实仍主要由 GitHub 一手事件独立支撑，不将两个 GitHub 链接称为双源。Cursor 当前可见 10 月 20 日 Agent SDK 是窗口外补查线索，不冒充今日发布；Audit Commons 的 www 地址不可访问，另查裸域，覆盖状态单独保存。历史空档没有据此补齐。</p><h2 id="github-存档与网站交付" tabindex="-1">GitHub 存档与网站交付 <a class="header-anchor" href="#github-存档与网站交付" aria-label="Permalink to &quot;GitHub 存档与网站交付&quot;">​</a></h2><p>本报告及英文镜像使用同一组 18 项事实、状态、来源与判断，仅更新当日日档与两个原索引；索引沿用现有样式和固定入口。源码写入通过已连接 GitHub 工具，源文件回读、最新 main/gh-pages 并发核对、现有站点构建、Pages 发布及中英文线上点击验收另存本地执行回执；本正文不预先声称部署成功。网站保留公开快照、原布局及其他已发布内容。未修改 Research Runtime 业务事实。</p>',103)])])}const d=a(n,[["render",p]]);export{u as __pageData,d as default};
